// Minimal TopoJSON client (feature only), API-compatible with topojson-client v3 `topojson.feature`.
// Bundled locally so the project runs without reaching unpkg.com.
(function (g) {
  function transformFn(t) {
    if (!t) return function (p) { return p.slice(); };
    var x0, y0, kx = t.scale[0], ky = t.scale[1], dx = t.translate[0], dy = t.translate[1];
    return function (input, i) {
      if (!i) x0 = y0 = 0;
      var out = input.slice();
      out[0] = (x0 += input[0]) * kx + dx;
      out[1] = (y0 += input[1]) * ky + dy;
      return out;
    };
  }
  function reverse(a, n) { var t, j = a.length, i = j - n; while (i < --j) { t = a[i]; a[i++] = a[j]; a[j] = t; } }
  function object(topology, o) {
    var tp = transformFn(topology.transform), arcs = topology.arcs;
    function arc(i, points) {
      if (points.length) points.pop();
      for (var a = arcs[i < 0 ? ~i : i], k = 0, n = a.length; k < n; ++k) points.push(tp(a[k], k));
      if (i < 0) reverse(points, n);
    }
    function point(p) { return tp(p); }
    function line(as) { var pts = []; for (var i = 0; i < as.length; ++i) arc(as[i], pts); if (pts.length < 2) pts.push(pts[0]); return pts; }
    function ring(as) { var pts = line(as); while (pts.length < 4) pts.push(pts[0]); return pts; }
    function polygon(as) { return as.map(ring); }
    function geometry(o) {
      var type = o.type, c;
      switch (type) {
        case "GeometryCollection": return { type: type, geometries: o.geometries.map(geometry) };
        case "Point": c = point(o.coordinates); break;
        case "MultiPoint": c = o.coordinates.map(point); break;
        case "LineString": c = line(o.arcs); break;
        case "MultiLineString": c = o.arcs.map(line); break;
        case "Polygon": c = polygon(o.arcs); break;
        case "MultiPolygon": c = o.arcs.map(polygon); break;
        default: return null;
      }
      return { type: type, coordinates: c };
    }
    return geometry(o);
  }
  function feature1(topology, o) {
    var f = { type: "Feature" };
    if (o.id != null) f.id = o.id;
    if (o.bbox != null) f.bbox = o.bbox;
    f.properties = o.properties == null ? {} : o.properties;
    f.geometry = object(topology, o);
    return f;
  }
  function feature(topology, o) {
    if (typeof o === "string") o = topology.objects[o];
    return o.type === "GeometryCollection"
      ? { type: "FeatureCollection", features: o.geometries.map(function (x) { return feature1(topology, x); }) }
      : feature1(topology, o);
  }
  g.topojson = Object.assign(g.topojson || {}, { feature: feature });
})(typeof window !== "undefined" ? window : globalThis);
